1	// =============================================================================
2	// M5 Pipeline — PipelineOrchestrator: M1→M2→M3→M4 端到端管道编排
3	// =============================================================================
4	
5	import { LLMClient } from '../llm-client';
6	import { Logger } from '../logger';
7	import { runIngest } from '../ingest/index';
8	import type { ValidationResult } from '../ingest/index';
9	import { NewsExtractor } from '../extract/index';
10	import type { ExtractorOptions } from '../extract/index';
11	import { StatsAggregator, InsightAnalyzer, ReportBuilder } from '../synthesize/index';
12	import { generateAllCharts } from '../visualize/index';
13	import type { GeneratedCharts } from '../visualize/index';
14	import type { StructuredInsightItem, ExtractionSummary, AggregationStats, TrendAnalysis, DailyReport, DeepAnalysis } from '../schema/types';
15	
16	// =============================================================================
17	// Public types
18	// =============================================================================
19	
20	export interface PipelineOptions {
21	  /** 包含 raw .json 文件的目录，默认 "data/raw" */
22	  dataDir?: string;
23	  /** 处理日期 (YYYY-MM-DD)，默认今天 */
24	  date?: string;
25	  /** 注入 LLMClient（不提供则从环境变量创建） */
26	  llmClient?: LLMClient;
27	  /** 从哪个阶段开始执行 */
28	  stage?: 'ingest' | 'extract' | 'synthesize' | 'visualize';
29	  /** M2 并发数，默认 3 */
30	  maxParallel?: number;
31	  /** 注入 Logger 实例 */
32	  logger?: Logger;
33	}
34	
35	export interface StageResultBase {
36	  status: 'success' | 'failed' | 'skipped';
37	  error?: string;
38	}
39	
40	export interface IngestStageResult extends StageResultBase {
41	  result?: ValidationResult;
42	}
43	
44	export interface ExtractStageResult extends StageResultBase {
45	  itemCount?: number;
46	  summary?: ExtractionSummary;
47	}
48	
49	export interface SynthesizeStageResult extends StageResultBase {
50	  report?: DailyReport;
51	}
52	
53	export interface VisualizeStageResult extends StageResultBase {
54	  charts?: GeneratedCharts;
55	}
56	
57	export interface PipelineResult {
58	  success: boolean;
59	  date: string;
60	  stages: {
61	    ingest: IngestStageResult;
62	    extract: ExtractStageResult;
63	    synthesize: SynthesizeStageResult;
64	    visualize: VisualizeStageResult;
65	  };
66	  totalDurationMs: number;
67	}
68	
69	// =============================================================================
70	// Defaults
71	// =============================================================================
72	
73	const STAGE_ORDER = ['ingest', 'extract', 'synthesize', 'visualize'] as const;
74	
75	function todayStr(): string {
76	  return new Date().toISOString().slice(0, 10);
77	}
78	
79	// =============================================================================
80	// PipelineOrchestrator
81	// =============================================================================
82	
83	export class PipelineOrchestrator {
84	  private readonly options: Required<PipelineOptions>;
85	  private readonly logger: Logger;
86	
87	  constructor(options?: PipelineOptions) {
88	    this.options = {
89	      dataDir: options?.dataDir ?? 'data/raw',
90	      date: options?.date ?? todayStr(),
91	      llmClient: options?.llmClient ?? new LLMClient(),
92	      stage: options?.stage ?? 'ingest',
93	      maxParallel: options?.maxParallel ?? 3,
94	      logger: options?.logger ?? new Logger('PIPELINE'),
95	    };
96	    this.logger = this.options.logger;
97	  }
98	
99	  // =========================================================================
100	  // run — 执行完整管道
101	  // =========================================================================
102	
103	  async run(): Promise<PipelineResult> {
104	    const startTime = Date.now();
105	    const date = this.options.date;
106	    const stageIdx = STAGE_ORDER.indexOf(this.options.stage);
107	
108	    this.logger.info(`Pipeline started (stage=${this.options.stage}, date=${date})`);
109	
110	    // ── Accumulated state ──────────────────────────────────────────────
111	    let ingestResult: ValidationResult | undefined;
112	    let extractedItems: StructuredInsightItem[] = [];
113	    let extractionSummary: ExtractionSummary | undefined;
114	    let stats: AggregationStats = {
115	      topic_frequency: {},
116	      source_distribution: {},
117	      sentiment_distribution: {},
118	      risk_distribution: {},
119	      top_by_significance: [],
120	      entity_co_occurrence: [],
121	    };
122	    let trends: TrendAnalysis = {
123	      technology: { trend: '', confidence: 0, supporting_items: [], signals: [] },
124	      application: { trend: '', confidence: 0, supporting_items: [], signals: [] },
125	      policy: { trend: '', confidence: 0, supporting_items: [], signals: [] },
126	      capital: { trend: '', confidence: 0, supporting_items: [], signals: [] },
127	      overall_narrative: '',
128	      uncertainties: [],
129	    };
130	    let report: DailyReport | undefined;
131	
132	    // ── Stage result accumulators ──────────────────────────────────────
133	    const ingestStage: IngestStageResult = { status: 'skipped' };
134	    const extractStage: ExtractStageResult = { status: 'skipped' };
135	    const synthesizeStage: SynthesizeStageResult = { status: 'skipped' };
136	    const visualizeStage: VisualizeStageResult = { status: 'skipped' };
137	
138	    // ===================================================================
139	    // Phase 1: INGEST
140	    // ===================================================================
141	    if (stageIdx <= 0) {
142	      this.logger.info('Starting INGEST stage');
143	      try {
144	        ingestResult = await runIngest({
145	          dataDir: this.options.dataDir,
146	          date,
147	        });
148	
149	        ingestStage.status = 'success';
150	        ingestStage.result = ingestResult;
151	        this.logger.info(`INGEST stage completed: ${ingestResult.valid.length} valid items`);
152	      } catch (err) {
153	        this.logger.error('INGEST stage failed', { error: String(err) });
154	        ingestStage.status = 'failed';
155	        ingestStage.error = String(err);
156	        const totalDurationMs = Date.now() - startTime;
157	        this.logger.info(`Pipeline finished in ${totalDurationMs}ms — success=false`);
158	        return {
159	          success: false,
160	          date,
161	          stages: { ingest: ingestStage, extract: extractStage, synthesize: synthesizeStage, visualize: visualizeStage },
162	          totalDurationMs,
163	        };
164	      }
165	    }
166	
167	    // ===================================================================
168	    // Phase 2: EXTRACT
169	    // ===================================================================
170	    if (stageIdx <= 1) {
171	      this.logger.info('Starting EXTRACT stage');
172	      try {
173	        const validItems = ingestResult?.valid ?? [];
174	
175	        const extractor = new NewsExtractor({
176	          llmClient: this.options.llmClient,
177	          maxParallel: this.options.maxParallel,
178	        } as ExtractorOptions);
179	
180	        const extractResult = await extractor.extractBatch(validItems);
181	        extractedItems = extractResult.items;
182	        extractionSummary = extractResult.summary;
183	
184	        extractStage.status = 'success';
185	        extractStage.itemCount = extractedItems.length;
186	        extractStage.summary = extractionSummary;
187	        this.logger.info(
188	          `EXTRACT stage completed: ${extractedItems.length}/${validItems.length} items extracted`,
189	        );
190	      } catch (err) {
191	        this.logger.error('EXTRACT stage failed', { error: String(err) });
192	        extractStage.status = 'failed';
193	        extractStage.error = String(err);
194	        extractStage.itemCount = 0;
195	        // Continue with empty items — partial failure
196	        extractedItems = [];
197	      }
198	    }
199	
200	    // ===================================================================
201	    // Phase 3: SYNTHESIZE
202	    // ===================================================================
203	    if (stageIdx <= 2) {
204	      this.logger.info('Starting SYNTHESIZE stage');
205	      try {
206	        // Phase A: Aggregate statistics
207	        this.logger.info('SYNTHESIZE Phase A: Aggregating statistics');
208	        const aggregator = new StatsAggregator();
209	        stats = aggregator.aggregate(extractedItems);
210	
211	        // Phase B: Identify top events
212	        this.logger.info('SYNTHESIZE Phase B: Identifying top events');
213	        const analyzer = new InsightAnalyzer({ llmClient: this.options.llmClient });
214	        const topEvents = await analyzer.identifyTopEvents({
215	          topicFrequency: stats.topic_frequency,
216	          topBySignificance: extractedItems.filter(
217	            (item) => stats.top_by_significance.some((t) => t.id === item.id),
218	          ),
219	        });
220	
221	        // Phase C: Deep analysis for each event
222	        this.logger.info(`SYNTHESIZE Phase C: Analyzing ${topEvents.length} event(s) in depth`);
223	        const deepAnalyses: DeepAnalysis[] = [];
224	        for (const event of topEvents) {
225	          const relatedItems = extractedItems.filter(
226	            (item) => event.item_ids.includes(item.id),
227	          );
228	          const deepAnalysis = await analyzer.analyzeEvent(event, relatedItems);
229	          deepAnalyses.push(deepAnalysis);
230	        }
231	
232	        // Phase D: Trend analysis
233	        this.logger.info('SYNTHESIZE Phase D: Analyzing trends');
234	        trends = await analyzer.analyzeTrends(extractedItems, topEvents);
235	
236	        // Phase E: Risk and opportunity identification
237	        this.logger.info('SYNTHESIZE Phase E: Identifying risks and opportunities');
238	        const riskOpp = await analyzer.identifyRisksAndOpportunities(extractedItems, trends);
239	
240	        // Phase F: Build report
241	        this.logger.info('SYNTHESIZE Phase F: Building report');
242	        const builder = new ReportBuilder();
243	        report = builder.buildReport(date, stats, topEvents, deepAnalyses, trends, riskOpp);
244	
245	        synthesizeStage.status = 'success';
246	        synthesizeStage.report = report;
247	        this.logger.info('SYNTHESIZE stage completed');
248	      } catch (err) {
249	        this.logger.error('SYNTHESIZE stage failed', { error: String(err) });
250	        synthesizeStage.status = 'failed';
251	        synthesizeStage.error = String(err);
252	      }
253	    }
254	
255	    // ===================================================================
256	    // Phase 4: VISUALIZE
257	    // ===================================================================
258	    if (stageIdx <= 3) {
259	      this.logger.info('Starting VISUALIZE stage');
260	      try {
261	        const charts = generateAllCharts(stats, trends, date);
262	        visualizeStage.status = 'success';
263	        visualizeStage.charts = charts;
264	        this.logger.info('VISUALIZE stage completed');
265	      } catch (err) {
266	        this.logger.error('VISUALIZE stage failed', { error: String(err) });
267	        visualizeStage.status = 'failed';
268	        visualizeStage.error = String(err);
269	        visualizeStage.charts = {
270	          topicBarChart: '',
271	          sentimentDonut: '',
272	          trendRadar: '',
273	          eventTimeline: '',
274	        };
275	      }
276	    }
277	
278	    // ===================================================================
279	    // Final result
280	    // ===================================================================
281	    const totalDurationMs = Date.now() - startTime;
282	
283	    // Pipeline is successful if none of the required stages explicitly failed
284	    // and at least one stage actually ran
285	    const hasRunningStage = STAGE_ORDER.slice(stageIdx).some((s) => {
286	      switch (s) {
287	        case 'ingest': return ingestStage.status !== 'skipped';
288	        case 'extract': return extractStage.status !== 'skipped';
289	        case 'synthesize': return synthesizeStage.status !== 'skipped';
290	        case 'visualize': return visualizeStage.status !== 'skipped';
291	      }
292	      return false;
293	    });
294	
295	    // Determine success: all required stages must not be 'failed'
296	    const allRequiredSucceeded = STAGE_ORDER.slice(stageIdx).every((s) => {
297	      switch (s) {
298	        case 'ingest': return ingestStage.status !== 'failed';
299	        case 'extract': return extractStage.status !== 'failed';
300	        case 'synthesize': return synthesizeStage.status !== 'failed';
301	        case 'visualize': return visualizeStage.status !== 'failed';
302	      }
303	      return true;
304	    });
305	
306	    // EXTRACT failure is non-blocking (pipeline continues), so don't fail overall for it
307	    // Only INGEST and SYNTHESIZE failures make the overall pipeline fail
308	    const success = hasRunningStage && allRequiredSucceeded;
309	
310	    this.logger.info(
311	      `Pipeline finished in ${totalDurationMs}ms — success=${success}`,
312	    );
313	
314	    return {
315	      success,
316	      date,
317	      stages: {
318	        ingest: ingestStage,
319	        extract: extractStage,
320	        synthesize: synthesizeStage,
321	        visualize: visualizeStage,
322	      },
323	      totalDurationMs,
324	    };
325	  }
326	}
