3	// ---------------------------------------------------------------------------
4	// Public types
5	// ---------------------------------------------------------------------------
6	
7	export interface LLMOptions {
8	  model?: string;
9	  maxTokens?: number;
10	  temperature?: number;
11	  timeout?: number;
12	}
13	
14	export interface LLMResponse {
15	  content: string;
16	  model: string;
17	  usage: {
18	    inputTokens: number;
19	    outputTokens: number;
20	  };
21	  durationMs: number;
22	}
23	
24	export interface LLMClientConfig {
25	  maxRetries?: number;   // default 3
26	  baseDelayMs?: number;  // default 1000
27	  apiKey?: string;       // default process.env.DEEPSEEK_API_KEY
28	}
29	
30	// ---------------------------------------------------------------------------
31	// Constants
32	// ---------------------------------------------------------------------------
33	
34	const DEFAULT_MODEL = 'deepseek-chat';
35	const DEFAULT_MAX_TOKENS = 4096;
36	const DEEPSEEK_BASE_URL = 'https://api.deepseek.com/v1';
37	
38	// ---------------------------------------------------------------------------
39	// Client
40	// ---------------------------------------------------------------------------
41	
42	export class LLMClient {
43	  private readonly client: OpenAI;
44	  private readonly maxRetries: number;
45	  private readonly baseDelayMs: number;
46	
47	  /**
48	   * @param config          Public config options.
49	   * @param config.openai   Optional pre-configured OpenAI SDK instance
50	   *                        (used for dependency injection / testing).
51	   */
52	  constructor(
53	    config?: LLMClientConfig & { openai?: OpenAI },
54	  ) {
55	    this.maxRetries = config?.maxRetries ?? 3;
56	    this.baseDelayMs = config?.baseDelayMs ?? 1000;
57	
58	    if (config?.openai) {
59	      this.client = config.openai;
60	    } else {
61	      this.client = new OpenAI({
62	        apiKey: config?.apiKey ?? process.env.DEEPSEEK_API_KEY,
63	        baseURL: DEEPSEEK_BASE_URL,
64	      });
65	    }
66	  }
67	
68	  // -----------------------------------------------------------------------
69	  // Public API
70	  // -----------------------------------------------------------------------
71	
72	  /**
73	   * Send a prompt to the LLM and receive a structured response.
74	   * Automatically retries on retry-able errors (network timeout, 429, 5xx).
75	   */
76	  async send(prompt: string, options?: LLMOptions): Promise<LLMResponse> {
77	    const startTime = Date.now();
78	
79	    for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
80	      try {
81	        const response = await this.client.chat.completions.create(
82	          {
83	            model: options?.model ?? DEFAULT_MODEL,
84	            messages: [{ role: 'user', content: prompt }],
85	            max_tokens: options?.maxTokens ?? DEFAULT_MAX_TOKENS,
86	            ...(options?.temperature !== undefined ? { temperature: options.temperature } : {}),
87	          },
88	          options?.timeout !== undefined ? { timeout: options.timeout } : {},
89	        );
90	
91	        const durationMs = Date.now() - startTime;
92	        const content = response.choices[0]?.message?.content ?? '';
93	        const model = response.model;
94	        const inputTokens = response.usage?.prompt_tokens ?? 0;
95	        const outputTokens = response.usage?.completion_tokens ?? 0;
96	
97	        return {
98	          content,
99	          model,
100	          usage: { inputTokens, outputTokens },
101	          durationMs,
102	        };
103	      } catch (err: unknown) {
104	        // If this is the last attempt, rethrow immediately.
105	        if (attempt >= this.maxRetries || !this.isRetryable(err)) {
106	          throw err;
107	        }
108	
109	        const delayMs = this.baseDelayMs * Math.pow(2, attempt);
110	        console.log(
111	          `[WARN] LLM call failed (attempt ${attempt + 1}/${this.maxRetries + 1}), retrying in ${delayMs}ms: ${(err as Error).message}`,
112	        );
113	        await this.sleep(delayMs);
114	      }
115	    }
116	
117	    // Unreachable -- the loop always returns or throws.
118	    throw new Error('Unexpected state in LLMClient.send');
119	  }
120	
121	  // -----------------------------------------------------------------------
122	  // Static factory
123	  // -----------------------------------------------------------------------
124	
125	  /**
126	   * Create a mock LLMClient that does **not** make real API calls.
127	   *
128	   * @param stubResponse  Return this LLMResponse on success, or throw this
129	   *                      Error on failure.  The full retry machinery is still
130	   *                      active so you can test retry exhaustion.
131	   */
132	  static createMock(stubResponse: LLMResponse | Error): LLMClient {
133	    const mockOpenAI = {
134	      chat: {
135	        completions: {
136	          create: async (): Promise<Record<string, unknown>> => {
137	            if (stubResponse instanceof Error) {
138	              throw stubResponse;
139	            }
140	            return {
141	              id: 'chatcmpl-mock-001',
142	              object: 'chat.completion',
143	              created: Date.now(),
144	              model: stubResponse.model,
145	              choices: [{
146	                index: 0,
147	                message: { role: 'assistant', content: stubResponse.content },
148	                finish_reason: 'stop',
149	              }],
150	              usage: {
151	                prompt_tokens: stubResponse.usage.inputTokens,
152	                completion_tokens: stubResponse.usage.outputTokens,
153	                total_tokens: stubResponse.usage.inputTokens + stubResponse.usage.outputTokens,
154	              },
155	            };
156	          },
157	        },
158	      },
159	    };
160	
161	    return new LLMClient({ openai: mockOpenAI as unknown as OpenAI });
162	  }
163	
164	  // -----------------------------------------------------------------------
165	  // Private helpers
166	  // -----------------------------------------------------------------------
167	
168	  /**
169	   * Determine whether an error is worth retrying.
170	   *
171	   * Retry-able:
172	   *   - Network / connection errors  (status === undefined)
173	   *   - HTTP 429 (rate-limit)
174	   *   - HTTP 5xx (server errors)
175	   *
176	   * Non-retry-able (thrown immediately):
177	   *   - HTTP 401 (auth)
178	   *   - HTTP 403 (permission)
179	   *   - HTTP 400 (bad request)
180	   */
181	  private isRetryable(err: unknown): boolean {
182	    const error = err as { status?: number };
183	    const status = error.status;
184	
185	    // Non-retry-able status codes
186	    if (status === 401 || status === 403 || status === 400) {
187	      return false;
188	    }
189	
190	    // Retry-able: rate limits, server errors, network timeouts
191	    if (status === 429) return true;
192	    if (status !== undefined && status >= 500) return true;
193	    if (status === undefined) return true; // e.g. APIConnectionTimeoutError
194	
195	    return false;
196	  }
197	
198	  /** Promise-based delay for retry back-off. */
199	  private sleep(ms: number): Promise<void> {
200	    return new Promise((resolve) => setTimeout(resolve, ms));
201	  }
202	}
