29	  /** M2 并发数，默认 3 */
30	  maxParallel?: number;
31	  /** 注入 Logger 实例 */
32	  logger?: Logger;
33	}
34	
35	export interface StageResultBase {
36	  status: 'success' | 'failed' | 'skipped';
37	  error?: string;
38	}
