57	export interface PipelineResult {
58	  success: boolean;
59	  date: string;
60	  stages: {
61	    ingest: IngestStageResult;
62	    extract: ExtractStageResult;
63	    synthesize: SynthesizeStageResult;
64	    visualize: VisualizeStageResult;
65	  };
66	  totalDurationMs: number;
