69	// =============================================================================
70	// Defaults
71	// =============================================================================
72	
73	const STAGE_ORDER = ['ingest', 'extract', 'synthesize', 'visualize'] as const;
74	
75	function todayStr(): string {
76	  return new Date().toISOString().slice(0, 10);
77	}
78	
79	// =============================================================================
80	// PipelineOrchestrator
81	// =============================================================================
82	
83	export class PipelineOrchestrator {
84	  private readonly options: Required<Omit<PipelineOptions, 'llmClient'>>;
85	  private readonly logger: Logger;
86	  private llmClientInstance?: LLMClient;
87	
88	  constructor(options?: PipelineOptions) {
89	    this.options = {
90	      dataDir: options?.dataDir ?? 'data/raw',
91	      date: options?.date ?? todayStr(),
92	      stage: options?.stage ?? 'ingest',
93	      maxParallel: options?.maxParallel ?? 3,
94	      logger: options?.logger ?? new Logger('PIPELINE'),
95	    };
96	    if (options?.llmClient) {
97	      this.llmClientInstance = options.llmClient;
98	    }
99	    this.logger = this.options.logger;
100	  }
101	
102	  // =========================================================================
103	  // run — 执行完整管道
104	  // =========================================================================
105	
106	  /**
107	   * 延迟获取 LLMClient：优先返回构造时注入的实例，否则在首次需要时创建。
108	   * 仅当需要 LLM 的阶段（extract/synthesize）运行时才会初始化。
109	   */
110	  private getLLMClient(): LLMClient {
111	    if (this.llmClientInstance) {
112	      return this.llmClientInstance;
113	    }
114	    const apiKey = process.env.DEEPSEEK_API_KEY || process.env.OPENAI_API_KEY;
115	    if (!apiKey) {
116	      throw new Error(
117	        'Missing API key. Set DEEPSEEK_API_KEY environment variable.\n' +
118	        '  Example: export DEEPSEEK_API_KEY="sk-..."',
119	      );
120	    }
121	    this.llmClientInstance = new LLMClient({ apiKey });
122	    this.logger.info('LLMClient initialized (lazy)');
123	    return this.llmClientInstance;
124	  }
125	
126	  async run(): Promise<PipelineResult> {
127	    const startTime = Date.now();
128	    const date = this.options.date;
129	    const stageIdx = STAGE_ORDER.indexOf(this.options.stage);
130	
131	    this.logger.info(`Pipeline started (stage=${this.options.stage}, date=${date})`);
132	
133	    // ── Accumulated state ──────────────────────────────────────────────
134	    let ingestResult: ValidationResult | undefined;
135	    let extractedItems: StructuredInsightItem[] = [];
136	    let extractionSummary: ExtractionSummary | undefined;
137	    let stats: AggregationStats = {
138	      topic_frequency: {},
139	      source_distribution: {},
140	      sentiment_distribution: {},
141	      risk_distribution: {},
142	      top_by_significance: [],
143	      entity_co_occurrence: [],
144	    };
145	    let trends: TrendAnalysis = {
146	      technology: { trend: '', confidence: 0, supporting_items: [], signals: [] },
147	      application: { trend: '', confidence: 0, supporting_items: [], signals: [] },
148	      policy: { trend: '', confidence: 0, supporting_items: [], signals: [] },
149	      capital: { trend: '', confidence: 0, supporting_items: [], signals: [] },
150	      overall_narrative: '',
151	      uncertainties: [],
152	    };
153	    let report: DailyReport | undefined;
154	
155	    // ── Stage result accumulators ──────────────────────────────────────
156	    const ingestStage: IngestStageResult = { status: 'skipped' };
157	    const extractStage: ExtractStageResult = { status: 'skipped' };
158	    const synthesizeStage: SynthesizeStageResult = { status: 'skipped' };
159	    const visualizeStage: VisualizeStageResult = { status: 'skipped' };
160	
161	    // ===================================================================
162	    // Phase 1: INGEST
163	    // ===================================================================
164	    if (stageIdx <= 0) {
165	      this.logger.info('Starting INGEST stage');
166	      try {
167	        ingestResult = await runIngest({
168	          dataDir: this.options.dataDir,
169	          date,
170	        });
171	
172	        ingestStage.status = 'success';
173	        ingestStage.result = ingestResult;
174	        this.logger.info(`INGEST stage completed: ${ingestResult.valid.length} valid items`);
175	      } catch (err) {
176	        this.logger.error('INGEST stage failed', { error: String(err) });
177	        ingestStage.status = 'failed';
178	        ingestStage.error = String(err);
179	        const totalDurationMs = Date.now() - startTime;
180	        this.logger.info(`Pipeline finished in ${totalDurationMs}ms — success=false`);
181	        return {
182	          success: false,
183	          date,
184	          stages: { ingest: ingestStage, extract: extractStage, synthesize: synthesizeStage, visualize: visualizeStage },
185	          totalDurationMs,
186	        };
187	      }
188	    }
189	
190	    // ===================================================================
191	    // Phase 2: EXTRACT
192	    // ===================================================================
193	    if (stageIdx <= 1) {
194	      this.logger.info('Starting EXTRACT stage');
195	      try {
196	        const validItems = ingestResult?.valid ?? [];
197	
198	        const extractor = new NewsExtractor({
199	          llmClient: this.getLLMClient(),
200	          maxParallel: this.options.maxParallel,
201	        } as ExtractorOptions);
202	
203	        const extractResult = await extractor.extractBatch(validItems);
204	        extractedItems = extractResult.items;
205	        extractionSummary = extractResult.summary;
206	
207	        extractStage.status = 'success';
208	        extractStage.itemCount = extractedItems.length;
209	        extractStage.summary = extractionSummary;
210	        this.logger.info(
211	          `EXTRACT stage completed: ${extractedItems.length}/${validItems.length} items extracted`,
212	        );
213	      } catch (err) {
214	        this.logger.error('EXTRACT stage failed', { error: String(err) });
215	        extractStage.status = 'failed';
216	        extractStage.error = String(err);
217	        extractStage.itemCount = 0;
218	        // Continue with empty items — partial failure
219	        extractedItems = [];
220	      }
221	    }
222	
223	    // ===================================================================
224	    // Phase 3: SYNTHESIZE
225	    // ===================================================================
226	    if (stageIdx <= 2) {
227	      this.logger.info('Starting SYNTHESIZE stage');
228	      try {
229	        // Phase A: Aggregate statistics
230	        this.logger.info('SYNTHESIZE Phase A: Aggregating statistics');
231	        const aggregator = new StatsAggregator();
232	        stats = aggregator.aggregate(extractedItems);
233	
234	        // Phase B: Identify top events
235	        this.logger.info('SYNTHESIZE Phase B: Identifying top events');
236	        const analyzer = new InsightAnalyzer({ llmClient: this.getLLMClient() });
237	        const topEvents = await analyzer.identifyTopEvents({
238	          topicFrequency: stats.topic_frequency,
239	          topBySignificance: extractedItems.filter(
240	            (item) => stats.top_by_significance.some((t) => t.id === item.id),
241	          ),
242	        });
243	
244	        // Phase C: Deep analysis for each event
245	        this.logger.info(`SYNTHESIZE Phase C: Analyzing ${topEvents.length} event(s) in depth`);
246	        const deepAnalyses: DeepAnalysis[] = [];
247	        for (const event of topEvents) {
248	          const relatedItems = extractedItems.filter(
249	            (item) => event.item_ids.includes(item.id),
250	          );
251	          const deepAnalysis = await analyzer.analyzeEvent(event, relatedItems);
252	          deepAnalyses.push(deepAnalysis);
253	        }
254	
255	        // Phase D: Trend analysis
256	        this.logger.info('SYNTHESIZE Phase D: Analyzing trends');
257	        trends = await analyzer.analyzeTrends(extractedItems, topEvents);
258	
259	        // Phase E: Risk and opportunity identification
260	        this.logger.info('SYNTHESIZE Phase E: Identifying risks and opportunities');
261	        const riskOpp = await analyzer.identifyRisksAndOpportunities(extractedItems, trends);
262	
263	        // Phase F: Build report
264	        this.logger.info('SYNTHESIZE Phase F: Building report');
265	        const builder = new ReportBuilder();
266	        report = builder.buildReport(date, stats, topEvents, deepAnalyses, trends, riskOpp);
267	
268	        synthesizeStage.status = 'success';
269	        synthesizeStage.report = report;
270	        this.logger.info('SYNTHESIZE stage completed');
271	      } catch (err) {
272	        this.logger.error('SYNTHESIZE stage failed', { error: String(err) });
273	        synthesizeStage.status = 'failed';
274	        synthesizeStage.error = String(err);
275	      }
276	    }
277	
278	    // ===================================================================
279	    // Phase 4: VISUALIZE
280	    // ===================================================================
281	    if (stageIdx <= 3) {
282	      this.logger.info('Starting VISUALIZE stage');
283	      try {
284	        const charts = generateAllCharts(stats, trends, date);
285	        visualizeStage.status = 'success';
286	        visualizeStage.charts = charts;
287	        this.logger.info('VISUALIZE stage completed');
288	      } catch (err) {
289	        this.logger.error('VISUALIZE stage failed', { error: String(err) });
290	        visualizeStage.status = 'failed';
291	        visualizeStage.error = String(err);
292	        visualizeStage.charts = {
293	          topicBarChart: '',
294	          sentimentDonut: '',
295	          trendRadar: '',
296	          eventTimeline: '',
297	        };
298	      }
299	    }
300	
301	    // ===================================================================
302	    // Final result
303	    // ===================================================================
304	    const totalDurationMs = Date.now() - startTime;
305	
306	    // Pipeline is successful if none of the required stages explicitly failed
307	    // and at least one stage actually ran
308	    const hasRunningStage = STAGE_ORDER.slice(stageIdx).some((s) => {
309	      switch (s) {
310	        case 'ingest': return ingestStage.status !== 'skipped';
311	        case 'extract': return extractStage.status !== 'skipped';
312	        case 'synthesize': return synthesizeStage.status !== 'skipped';
313	        case 'visualize': return visualizeStage.status !== 'skipped';
314	      }
315	      return false;
316	    });
317	
318	    // Determine success: all required stages must not be 'failed'
319	    const allRequiredSucceeded = STAGE_ORDER.slice(stageIdx).every((s) => {
320	      switch (s) {
321	        case 'ingest': return ingestStage.status !== 'failed';
322	        case 'extract': return extractStage.status !== 'failed';
323	        case 'synthesize': return synthesizeStage.status !== 'failed';
324	        case 'visualize': return visualizeStage.status !== 'failed';
325	      }
326	      return true;
327	    });
328	
329	    // EXTRACT failure is non-blocking (pipeline continues), so don't fail overall for it
330	    // Only INGEST and SYNTHESIZE failures make the overall pipeline fail
331	    const success = hasRunningStage && allRequiredSucceeded;
332	
333	    this.logger.info(
334	      `Pipeline finished in ${totalDurationMs}ms — success=${success}`,
335	    );
336	
337	    return {
338	      success,
339	      date,
340	      stages: {
341	        ingest: ingestStage,
342	        extract: extractStage,
343	        synthesize: synthesizeStage,
344	        visualize: visualizeStage,
345	      },
346	      totalDurationMs,
347	    };
348	  }
